-- Aditiva. Aplicar tras 002, 003 y 004. Distribución en planta, medidores y lecturas, servicios comunes y registro para deshacer.
ALTER TABLE spaces ADD COLUMN plan_x DOUBLE NULL, ADD COLUMN plan_y DOUBLE NULL, ADD COLUMN plan_w DOUBLE NULL, ADD COLUMN plan_d DOUBLE NULL;
CREATE TABLE IF NOT EXISTS meters (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,kind ENUM('general','sub') NOT NULL DEFAULT 'general',scope ENUM('building','floor','space') NOT NULL DEFAULT 'building',floor_id INT UNSIGNED NULL,space_id INT UNSIGNED NULL,parent_id INT UNSIGNED NULL,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,FOREIGN KEY(floor_id) REFERENCES floors(id) ON DELETE CASCADE,FOREIGN KEY(space_id) REFERENCES spaces(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES meters(id) ON DELETE SET NULL,INDEX(building_id));
CREATE TABLE IF NOT EXISTS meter_readings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id INT UNSIGNED NOT NULL,reading_date DATE NOT NULL,value DOUBLE NOT NULL,FOREIGN KEY(meter_id) REFERENCES meters(id) ON DELETE CASCADE,UNIQUE(meter_id,reading_date),CHECK(value>=0));
CREATE TABLE IF NOT EXISTS common_loads (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id INT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,category VARCHAR(50) NOT NULL DEFAULT 'Otro',calculation_mode ENUM('power','monthly') NOT NULL DEFAULT 'power',quantity INT UNSIGNED NOT NULL DEFAULT 1,watts DOUBLE NULL,hours DOUBLE NULL,days TINYINT UNSIGNED NULL,factor DOUBLE NOT NULL DEFAULT 1,monthly_kwh DOUBLE NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,INDEX(building_id),CHECK(quantity BETWEEN 1 AND 1000));
CREATE TABLE IF NOT EXISTS undo_log (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,building_id INT UNSIGNED NOT NULL,org_user_id INT UNSIGNED NULL,op VARCHAR(30) NOT NULL,label VARCHAR(200) NOT NULL,payload JSON NOT NULL,after_revision BIGINT UNSIGNED NOT NULL,undone BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(building_id) REFERENCES buildings(id) ON DELETE CASCADE,INDEX(building_id,undone,id));
